import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-BJYidpcE.js";var l=JSON.parse(`{"path":"/ai-framework/langchain-nestjs.html","title":"NestJS 中使用 LangChain.js","lang":"en-US","frontmatter":{},"git":{"updatedTime":1785804532000,"contributors":[{"name":"vlily","username":"vlily","email":"vlily@vlilydeMacBook-Pro.local","commits":1,"url":"https://github.com/vlily"}],"changelog":[{"hash":"ddd6163bcd8435bd3ec9adfbbacac400f80f5418","time":1785804532000,"email":"vlily@vlilydeMacBook-Pro.local","author":"vlily","message":"docs(ai-framework): add LangChain.js TypeScript 与 NestJS 集成教程"}]},"filePathRelative":"ai-framework/langchain-nestjs.md"}`),u={name:`langchain-nestjs.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[3]||=n(`<h1 id="nestjs-中使用-langchain-js" tabindex="-1"><a class="header-anchor" href="#nestjs-中使用-langchain-js"><span>NestJS 中使用 LangChain.js</span></a></h1><blockquote><p>零基础教程：把上文的 <a href="./langchain-typescript">LangChain.js 入门（TypeScript 版）</a> 搬到 NestJS 里，做成真实的 HTTP 接口。 适合：已经会 NestJS 基础（Controller / Service / Module），想给后端接大模型能力的同学。</p></blockquote><h2 id="为什么要在-nestjs-里用-langchain-js" tabindex="-1"><a class="header-anchor" href="#为什么要在-nestjs-里用-langchain-js"><span>为什么要在 NestJS 里用 LangChain.js？</span></a></h2><p>前端页面调大模型，不能直接把 API Key 放浏览器里（会泄露、有跨域问题）。所以常规做法是：</p><div class="language-markdown line-numbers-mode" data-highlighter="prismjs" data-ext="md"><pre><code class="language-markdown"><span class="line">前端页面 ──HTTP──→ NestJS 后端 ──LangChain.js──→ 大模型 API</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><strong>安全</strong>：API Key 只存在后端环境变量里</li><li><strong>统一</strong>：LLM 调用、对话历史、工具/Agent 都在一个工程里管理</li><li><strong>复用</strong>：多个前端页面共用同一个 AI 接口</li></ul><p>NestJS 的模块化（Module / Controller / Service）天然适合把「AI 能力」封装成一个独立模块，就像封装一个普通的后端功能。</p><hr><h2 id="一、安装依赖" tabindex="-1"><a class="header-anchor" href="#一、安装依赖"><span>一、安装依赖</span></a></h2><p>在 NestJS 项目里安装 LangChain 相关包：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">npm</span> <span class="token function">install</span> langchain @langchain/openai dotenv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>再安装环境变量加载：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">npm</span> <span class="token function">install</span> @nestjs/config</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>创建 <code>.env</code>：</p><div class="language-env line-numbers-mode" data-highlighter="prismjs" data-ext="env"><pre><code class="language-env"><span class="line">OPENAI_API_KEY=sk-xxxxx</span>
<span class="line"># 用国内模型也可以，比如 DeepSeek：</span>
<span class="line"># OPENAI_API_KEY=sk-xxx</span>
<span class="line"># OPENAI_BASE_URL=https://api.deepseek.com</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、加载环境变量-configmodule" tabindex="-1"><a class="header-anchor" href="#二、加载环境变量-configmodule"><span>二、加载环境变量（ConfigModule）</span></a></h2><p>在 <code>app.module.ts</code> 里全局引入 <code>ConfigModule</code>，让所有模块都能用 <code>.env</code> 里的配置：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/app.module.ts</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> Module <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/common&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ConfigModule <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatModule <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./chat/chat.module&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Module</span></span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  imports<span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token comment">// 加载 .env 并设为全局，这样 ChatModule 里也能用</span></span>
<span class="line">    ConfigModule<span class="token punctuation">.</span><span class="token function">forRoot</span><span class="token punctuation">(</span><span class="token punctuation">{</span> isGlobal<span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    ChatModule<span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">AppModule</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="三、创建-chat-模块-cli-三件套" tabindex="-1"><a class="header-anchor" href="#三、创建-chat-模块-cli-三件套"><span>三、创建 Chat 模块（CLI 三件套）</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">nest g module chat</span>
<span class="line">nest g controller chat</span>
<span class="line">nest g <span class="token function">service</span> chat</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>生成目录结构：</p><div class="language-markdown line-numbers-mode" data-highlighter="prismjs" data-ext="md"><pre><code class="language-markdown"><span class="line">src/chat/</span>
<span class="line">├── chat.controller.ts   ← 接收 HTTP 请求</span>
<span class="line">├── chat.module.ts       ← 注册 Controller 和 Service</span>
<span class="line">└── chat.service.ts      ← 写 LangChain 逻辑</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、写一个最简-ai-接口" tabindex="-1"><a class="header-anchor" href="#四、写一个最简-ai-接口"><span>四、写一个最简 AI 接口</span></a></h2><h3 id="_1-service-把-langchain-调用封装成方法" tabindex="-1"><a class="header-anchor" href="#_1-service-把-langchain-调用封装成方法"><span>1. Service：把 LangChain 调用封装成方法</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/chat/chat.service.ts</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> Injectable <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/common&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ConfigService <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Injectable</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">ChatService</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 用 ConfigService 读取 .env，不在代码里写死 Key</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token keyword">private</span> <span class="token keyword">readonly</span> configService<span class="token operator">:</span> ConfigService<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 创建一个模型实例（每次调用前先 new 一个，简单好理解）</span></span>
<span class="line">  <span class="token keyword">private</span> <span class="token function">createModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      apiKey<span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>configService<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;OPENAI_API_KEY&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span><span class="token punctuation">,</span></span>
<span class="line">      temperature<span class="token operator">:</span> <span class="token number">0.7</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 最简调用：提问，返回回答</span></span>
<span class="line">  <span class="token keyword">async</span> <span class="token function">ask</span><span class="token punctuation">(</span>question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">Promise</span><span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">createModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> model<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span>question<span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment">// response.content 是模型返回的内容</span></span>
<span class="line">    <span class="token keyword">return</span> response<span class="token punctuation">.</span>content <span class="token keyword">as</span> <span class="token builtin">string</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-controller-暴露-http-接口" tabindex="-1"><a class="header-anchor" href="#_2-controller-暴露-http-接口"><span>2. Controller：暴露 HTTP 接口</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/chat/chat.controller.ts</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> Controller<span class="token punctuation">,</span> Post<span class="token punctuation">,</span> Body <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/common&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatService <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./chat.service&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Controller</span></span><span class="token punctuation">(</span><span class="token string">&#39;chat&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">ChatController</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token keyword">private</span> <span class="token keyword">readonly</span> chatService<span class="token operator">:</span> ChatService<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// POST /chat/ask</span></span>
<span class="line">  <span class="token comment">// 请求体：{ &quot;question&quot;: &quot;什么是大模型？&quot; }</span></span>
<span class="line">  <span class="token decorator"><span class="token at operator">@</span><span class="token function">Post</span></span><span class="token punctuation">(</span><span class="token string">&#39;ask&#39;</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">async</span> <span class="token function">ask</span><span class="token punctuation">(</span><span class="token decorator"><span class="token at operator">@</span><span class="token function">Body</span></span><span class="token punctuation">(</span><span class="token string">&#39;question&#39;</span><span class="token punctuation">)</span> question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> answer <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>chatService<span class="token punctuation">.</span><span class="token function">ask</span><span class="token punctuation">(</span>question<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span> question<span class="token punctuation">,</span> answer <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-测试" tabindex="-1"><a class="header-anchor" href="#_3-测试"><span>3. 测试</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">npm</span> run start:dev</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>用 Apifox 发请求：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line">POST http<span class="token operator">:</span><span class="token comment">//localhost:3000/chat/ask</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;question&quot;</span><span class="token operator">:</span> <span class="token string">&quot;用一句话解释什么是大模型&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>返回：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;question&quot;</span><span class="token operator">:</span> <span class="token string">&quot;用一句话解释什么是大模型&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;answer&quot;</span><span class="token operator">:</span> <span class="token string">&quot;大模型是一种在海量数据上训练出来的巨型神经网络，能够理解和生成自然语言。&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="五、流式输出-sse-聊天界面的标准做法" tabindex="-1"><a class="header-anchor" href="#五、流式输出-sse-聊天界面的标准做法"><span>五、流式输出（SSE，聊天界面的标准做法）</span></a></h2><p>聊天界面要一个字一个字蹦出来，就得用「流式输出」。前端用 <code>EventSource</code> 或 <code>fetch</code> 读流，后端用 <code>@Sse()</code> 返回。</p><blockquote><p>SSE（Server-Sent Events）就是后端「持续往一个响应里写数据」的 HTTP 协议，非常适合 LLM 逐字输出。</p></blockquote><h3 id="_1-controller-加一个-sse-接口" tabindex="-1"><a class="header-anchor" href="#_1-controller-加一个-sse-接口"><span>1. Controller：加一个 SSE 接口</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/chat/chat.controller.ts</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> Controller<span class="token punctuation">,</span> Post<span class="token punctuation">,</span> Body<span class="token punctuation">,</span> Sse <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/common&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> Observable<span class="token punctuation">,</span> from <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;rxjs&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatService <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./chat.service&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Controller</span></span><span class="token punctuation">(</span><span class="token string">&#39;chat&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">ChatController</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token keyword">private</span> <span class="token keyword">readonly</span> chatService<span class="token operator">:</span> ChatService<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token decorator"><span class="token at operator">@</span><span class="token function">Post</span></span><span class="token punctuation">(</span><span class="token string">&#39;ask&#39;</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">async</span> <span class="token function">ask</span><span class="token punctuation">(</span><span class="token decorator"><span class="token at operator">@</span><span class="token function">Body</span></span><span class="token punctuation">(</span><span class="token string">&#39;question&#39;</span><span class="token punctuation">)</span> question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span> question<span class="token punctuation">,</span> answer<span class="token operator">:</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>chatService<span class="token punctuation">.</span><span class="token function">ask</span><span class="token punctuation">(</span>question<span class="token punctuation">)</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// POST /chat/stream</span></span>
<span class="line">  <span class="token comment">// 返回一个 Observable，NestJS 会自动转成 SSE 流</span></span>
<span class="line">  <span class="token decorator"><span class="token at operator">@</span><span class="token function">Post</span></span><span class="token punctuation">(</span><span class="token string">&#39;stream&#39;</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token function">stream</span><span class="token punctuation">(</span><span class="token decorator"><span class="token at operator">@</span><span class="token function">Body</span></span><span class="token punctuation">(</span><span class="token string">&#39;question&#39;</span><span class="token punctuation">)</span> question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> Observable<span class="token operator">&lt;</span><span class="token builtin">any</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>chatService<span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span>question<span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-service-用-langchain-的-stream-方法" tabindex="-1"><a class="header-anchor" href="#_2-service-用-langchain-的-stream-方法"><span>2. Service：用 LangChain 的 stream 方法</span></a></h3><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/chat/chat.service.ts</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> Injectable <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/common&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ConfigService <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> Observable<span class="token punctuation">,</span> from <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;rxjs&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> StringOutputParser <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/output_parsers&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Injectable</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">ChatService</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token keyword">private</span> <span class="token keyword">readonly</span> configService<span class="token operator">:</span> ConfigService<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 流式：返回一个「一段一段吐字」的可观察对象</span></span>
<span class="line">  <span class="token function">stream</span><span class="token punctuation">(</span>question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> Observable<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      apiKey<span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>configService<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;OPENAI_API_KEY&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span><span class="token punctuation">,</span></span>
<span class="line">      streaming<span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token comment">// 开启流式</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// StringOutputParser 把每段数据转成纯字符串</span></span>
<span class="line">    <span class="token keyword">const</span> parser <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">StringOutputParser</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">const</span> stream <span class="token operator">=</span> model<span class="token punctuation">.</span><span class="token function">pipe</span><span class="token punctuation">(</span>parser<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">stream</span><span class="token punctuation">(</span>question<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 把异步迭代器包装成 RxJS Observable，NestJS 就能识别成 SSE</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token function">from</span><span class="token punctuation">(</span>stream<span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-前端怎么接" tabindex="-1"><a class="header-anchor" href="#_3-前端怎么接"><span>3. 前端怎么接？</span></a></h3><p>前端用 <code>fetch</code> 读取流（浏览器端直接用 POST + SSE 需要自己处理，或用 <code>@microsoft/fetch-event-source</code>）：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> res <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;/chat/stream&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">  method<span class="token operator">:</span> <span class="token string">&#39;POST&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  headers<span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token string-property property">&#39;Content-Type&#39;</span><span class="token operator">:</span> <span class="token string">&#39;application/json&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  body<span class="token operator">:</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span><span class="token punctuation">{</span> question<span class="token operator">:</span> <span class="token string">&#39;讲个笑话&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 读取响应流，一段段拼接文字</span></span>
<span class="line"><span class="token keyword">const</span> reader <span class="token operator">=</span> res<span class="token punctuation">.</span>body<span class="token operator">!</span><span class="token punctuation">.</span><span class="token function">getReader</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">const</span> decoder <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">TextDecoder</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">let</span> text <span class="token operator">=</span> <span class="token string">&#39;&#39;</span></span>
<span class="line"><span class="token keyword">while</span> <span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">{</span> done<span class="token punctuation">,</span> value <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token keyword">await</span> reader<span class="token punctuation">.</span><span class="token function">read</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>done<span class="token punctuation">)</span> <span class="token keyword">break</span></span>
<span class="line">  text <span class="token operator">+=</span> decoder<span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span></span>
<span class="line">  <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;当前已输出的文字：&#39;</span><span class="token punctuation">,</span> text<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>记得在 <code>main.ts</code> 里给 NestJS 开启 CORS，前端才能跨域调用：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">const</span> app <span class="token operator">=</span> <span class="token keyword">await</span> NestFactory<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span>AppModule<span class="token punctuation">)</span></span>
<span class="line">app<span class="token punctuation">.</span><span class="token function">enableCors</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// 允许前端跨域</span></span>
<span class="line"><span class="token keyword">await</span> app<span class="token punctuation">.</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token number">3000</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></blockquote><hr><h2 id="六、带对话历史-memory" tabindex="-1"><a class="header-anchor" href="#六、带对话历史-memory"><span>六、带对话历史（Memory）</span></a></h2><p>真实聊天要记住上下文。用 <code>RunnableWithMessageHistory</code>，每个用户一个 <code>sessionId</code>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/chat/chat.service.ts</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> Injectable <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/common&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ConfigService <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@nestjs/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatPromptTemplate<span class="token punctuation">,</span> MessagesPlaceholder <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/prompts&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> RunnableWithMessageHistory <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/runnables&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> InMemoryChatMessageHistory <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/chats_helpers&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Injectable</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">ChatService</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token keyword">private</span> <span class="token keyword">readonly</span> configService<span class="token operator">:</span> ConfigService<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 用一个 Map 存每个用户的历史（生产环境换成 Redis / 数据库）</span></span>
<span class="line">  <span class="token keyword">private</span> histories <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Map<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> InMemoryChatMessageHistory<span class="token operator">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">private</span> <span class="token function">getHistory</span><span class="token punctuation">(</span>sessionId<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span>histories<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>sessionId<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">this</span><span class="token punctuation">.</span>histories<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span>sessionId<span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token class-name">InMemoryChatMessageHistory</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>histories<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>sessionId<span class="token punctuation">)</span><span class="token operator">!</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">async</span> <span class="token function">chat</span><span class="token punctuation">(</span>question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span> sessionId<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">Promise</span><span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      apiKey<span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>configService<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;OPENAI_API_KEY&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">const</span> prompt <span class="token operator">=</span> ChatPromptTemplate<span class="token punctuation">.</span><span class="token function">fromMessages</span><span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">[</span><span class="token string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;你是一个友好的助手，用中文回答。&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token keyword">new</span> <span class="token class-name">MessagesPlaceholder</span><span class="token punctuation">(</span><span class="token string">&#39;history&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token comment">// 历史消息插在这里</span></span>
<span class="line">      <span class="token punctuation">[</span><span class="token string">&#39;human&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;{input}&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">const</span> chain <span class="token operator">=</span> prompt<span class="token punctuation">.</span><span class="token function">pipe</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">const</span> chainWithHistory <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">RunnableWithMessageHistory</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      runnable<span class="token operator">:</span> chain<span class="token punctuation">,</span></span>
<span class="line">      <span class="token function-variable function">getMessageHistory</span><span class="token operator">:</span> <span class="token keyword">async</span> <span class="token punctuation">(</span>sid<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">getHistory</span><span class="token punctuation">(</span>sid<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      inputMessagesKey<span class="token operator">:</span> <span class="token string">&#39;input&#39;</span><span class="token punctuation">,</span></span>
<span class="line">      historyMessagesKey<span class="token operator">:</span> <span class="token string">&#39;history&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> chainWithHistory<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span></span>
<span class="line">      <span class="token punctuation">{</span> input<span class="token operator">:</span> question <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span> configurable<span class="token operator">:</span> <span class="token punctuation">{</span> sessionId <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> response<span class="token punctuation">.</span>content <span class="token keyword">as</span> <span class="token builtin">string</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Controller 接收两个参数：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/chat/chat.controller.ts</span></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Post</span></span><span class="token punctuation">(</span><span class="token string">&#39;chat&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token function">chat</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token decorator"><span class="token at operator">@</span><span class="token function">Body</span></span><span class="token punctuation">(</span><span class="token string">&#39;question&#39;</span><span class="token punctuation">)</span> question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token decorator"><span class="token at operator">@</span><span class="token function">Body</span></span><span class="token punctuation">(</span><span class="token string">&#39;sessionId&#39;</span><span class="token punctuation">)</span> sessionId<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token comment">// 前端每次带上用户 ID</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> answer <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>chatService<span class="token punctuation">.</span><span class="token function">chat</span><span class="token punctuation">(</span>question<span class="token punctuation">,</span> sessionId<span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> sessionId<span class="token punctuation">,</span> answer <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>测试两次对话，同一个 <code>sessionId</code> 就能记上下文：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line">POST /chat/chat</span>
<span class="line"><span class="token punctuation">{</span> <span class="token property">&quot;sessionId&quot;</span><span class="token operator">:</span> <span class="token string">&quot;user-001&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;question&quot;</span><span class="token operator">:</span> <span class="token string">&quot;我叫小明&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// → &quot;你好小明！&quot;</span></span>
<span class="line"></span>
<span class="line">POST /chat/chat</span>
<span class="line"><span class="token punctuation">{</span> <span class="token property">&quot;sessionId&quot;</span><span class="token operator">:</span> <span class="token string">&quot;user-001&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;question&quot;</span><span class="token operator">:</span> <span class="token string">&quot;我叫什么名字？&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// → &quot;你叫小明。&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="七、工具-agent-让后端能力被模型调用" tabindex="-1"><a class="header-anchor" href="#七、工具-agent-让后端能力被模型调用"><span>七、工具 + Agent（让后端能力被模型调用）</span></a></h2><p>把后端现有的方法（查订单、查天气、调数据库）包装成 Tool，Agent 会自动决定调哪个：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/chat/chat.service.ts</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> tool <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/tools&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> z <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;zod&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> createReactAgent <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/langgraph/prebuilt&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Injectable</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">ChatService</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token keyword">private</span> <span class="token keyword">readonly</span> configService<span class="token operator">:</span> ConfigService<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">private</span> <span class="token keyword">async</span> <span class="token function">createAgent</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      apiKey<span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>configService<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;OPENAI_API_KEY&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 1. 定义工具：查询订单状态（真实项目里查数据库）</span></span>
<span class="line">    <span class="token keyword">const</span> checkOrder <span class="token operator">=</span> <span class="token function">tool</span><span class="token punctuation">(</span></span>
<span class="line">      <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> orderId <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">订单 </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>orderId<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> 已发货，预计 3 天内到达</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        name<span class="token operator">:</span> <span class="token string">&#39;check_order&#39;</span><span class="token punctuation">,</span></span>
<span class="line">        description<span class="token operator">:</span> <span class="token string">&#39;查询订单状态&#39;</span><span class="token punctuation">,</span></span>
<span class="line">        schema<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">object</span><span class="token punctuation">(</span><span class="token punctuation">{</span> orderId<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">string</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. 创建 Agent：模型自己决定调不调工具</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token function">createReactAgent</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      llm<span class="token operator">:</span> model<span class="token punctuation">,</span></span>
<span class="line">      tools<span class="token operator">:</span> <span class="token punctuation">[</span>checkOrder<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">async</span> <span class="token function">askWithAgent</span><span class="token punctuation">(</span>question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">Promise</span><span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> agent <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">createAgent</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token keyword">await</span> agent<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      messages<span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> role<span class="token operator">:</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> content<span class="token operator">:</span> question <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">const</span> lastMessage <span class="token operator">=</span> result<span class="token punctuation">.</span>messages<span class="token punctuation">[</span>result<span class="token punctuation">.</span>messages<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span></span>
<span class="line">    <span class="token keyword">return</span> lastMessage<span class="token punctuation">.</span>content <span class="token keyword">as</span> <span class="token builtin">string</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Controller：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// src/chat/chat.controller.ts</span></span>
<span class="line"><span class="token decorator"><span class="token at operator">@</span><span class="token function">Post</span></span><span class="token punctuation">(</span><span class="token string">&#39;agent&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token function">askWithAgent</span><span class="token punctuation">(</span><span class="token decorator"><span class="token at operator">@</span><span class="token function">Body</span></span><span class="token punctuation">(</span><span class="token string">&#39;question&#39;</span><span class="token punctuation">)</span> question<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> question<span class="token punctuation">,</span> answer<span class="token operator">:</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>chatService<span class="token punctuation">.</span><span class="token function">askWithAgent</span><span class="token punctuation">(</span>question<span class="token punctuation">)</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>测试：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line">POST /chat/agent</span>
<span class="line"><span class="token punctuation">{</span> <span class="token property">&quot;question&quot;</span><span class="token operator">:</span> <span class="token string">&quot;帮我查一下订单 12345 到哪了？&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// → &quot;订单 12345 已发货，预计 3 天内到达&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>模型自己判断出「这是订单查询」，自动调用了 <code>checkOrder</code> 工具——不需要你写任何 if/else 判断。</p><hr><h2 id="八、完整工程目录-参考" tabindex="-1"><a class="header-anchor" href="#八、完整工程目录-参考"><span>八、完整工程目录（参考）</span></a></h2><div class="language-markdown line-numbers-mode" data-highlighter="prismjs" data-ext="md"><pre><code class="language-markdown"><span class="line">src/</span>
<span class="line">├── main.ts                ← 入口，开启 CORS</span>
<span class="line">├── app.module.ts          ← 根模块，引入 ConfigModule + ChatModule</span>
<span class="line">└── chat/</span>
<span class="line">    ├── chat.module.ts     ← providers 注册 ChatService</span>
<span class="line">    ├── chat.controller.ts ← /chat/ask、/chat/stream、/chat/chat、/chat/agent</span>
<span class="line">    ├── chat.service.ts    ← 所有 LangChain 逻辑</span>
<span class="line">    └── dto/               ← 可选：用 DTO 校验请求体</span>
<span class="line">        └── ask.dto.ts</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>接口清单：</p><table><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td>/chat/ask</td><td>一次性问答</td></tr><tr><td>POST</td><td>/chat/stream</td><td>SSE 流式输出</td></tr><tr><td>POST</td><td>/chat/chat</td><td>带对话历史</td></tr><tr><td>POST</td><td>/chat/agent</td><td>工具 + Agent</td></tr></tbody></table><hr><h2 id="九、常见问题" tabindex="-1"><a class="header-anchor" href="#九、常见问题"><span>九、常见问题</span></a></h2><h3 id="_1-api-key-泄露到代码里了" tabindex="-1"><a class="header-anchor" href="#_1-api-key-泄露到代码里了"><span>1. API Key 泄露到代码里了</span></a></h3><p>把 Key 写在 <code>.env</code>，通过 <code>ConfigService</code> 读取。<code>.env</code> 记得加进 <code>.gitignore</code>。</p><h3 id="_2-前端跨域报错" tabindex="-1"><a class="header-anchor" href="#_2-前端跨域报错"><span>2. 前端跨域报错</span></a></h3><p>在 <code>main.ts</code> 里 <code>app.enableCors()</code>。</p><h3 id="_3-服务一直转圈不返回" tabindex="-1"><a class="header-anchor" href="#_3-服务一直转圈不返回"><span>3. 服务一直转圈不返回</span></a></h3><p>检查是不是没加 <code>await</code>。NestJS 方法返回 Promise，Controller 里要 <code>await this.chatService.xxx()</code>。</p><h3 id="_4-对话记不住上文" tabindex="-1"><a class="header-anchor" href="#_4-对话记不住上文"><span>4. 对话记不住上文</span></a></h3><p>确认每次请求都带了同一个 <code>sessionId</code>；生产环境把内存 Map 换成 Redis。</p><hr><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p>在 NestJS 里用 LangChain.js，本质就是：</p><div class="language-markdown line-numbers-mode" data-highlighter="prismjs" data-ext="md"><pre><code class="language-markdown"><span class="line">Controller（接 HTTP）→ Service（封装 LangChain）→ 大模型 API</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>你只需要写一个 <code>ChatService</code>，把 <code>ask</code> / <code>stream</code> / <code>chat</code> / <code>agent</code> 这几个方法封装好，前端就能像调用普通后端接口一样用上大模型。</p><hr><h2 id="下一步" tabindex="-1"><a class="header-anchor" href="#下一步"><span>下一步</span></a></h2>`,87),i(`ul`,null,[l[1]||=i(`li`,null,[i(`a`,{href:`./langchain-typescript`},`LangChain.js 入门（TypeScript 版）`)],-1),i(`li`,null,[a(m,{to:`/backend/nestjs.html`},{default:r(()=>[...l[0]||=[e(`NestJS 零基础入门`,-1)]]),_:1})]),l[2]||=i(`li`,null,[i(`a`,{href:`https://js.langchain.com/`,target:`_blank`,rel:`noopener noreferrer`},`LangChain.js 官方文档`)],-1)])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};